def write(name, obj):
    p = ROOT / name
    if p.exists():
        raise RuntimeError(f'Frozen file exists: {p}')
    p.write_text(json.dumps(obj, indent=2, ensure_ascii=False) + '\n')
    (ROOT / (name + '.sha256')).write_text(hashlib.sha256(p.read_bytes()).hexdigest() + '\n')

def main():
    records = {}
    for (key, p) in SOURCES.items():
        b = p.read_bytes()
        suffix = p.suffix
        dest = ROOT / 'raw' / ('input_' + key + suffix)
        dest.write_bytes(b)
        records[key] = {'source': str(p), 'snapshot': str(dest.relative_to(ROOT)), 'sha256': hashlib.sha256(b).hexdigest(), 'bytes': len(b)}
    write('INPUT_LOCK.json', records)
